using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests;

public static class TestHelpers
{
    public static SchoolContext CreateContext(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        return new SchoolContext(options);
    }

    public static void SeedStudents(SchoolContext context)
    {
        context.Students.AddRange(
            new Student { ID = 1, FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { ID = 2, FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { ID = 3, FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = new DateTime(2022, 9, 1) }
        );
        context.SaveChanges();
    }

    public static void SeedInstructors(SchoolContext context)
    {
        context.Instructors.AddRange(
            new Instructor
            {
                ID = 10, FirstMidName = "Kim", LastName = "Abercrombie",
                HireDate = new DateTime(1995, 3, 11),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 10, Location = "Smith 17" }
            },
            new Instructor
            {
                ID = 11, FirstMidName = "Fadi", LastName = "Fakhouri",
                HireDate = new DateTime(2002, 7, 6),
                CourseAssignments = new List<CourseAssignment>()
            }
        );
        context.SaveChanges();
    }

    public static void SeedDepartments(SchoolContext context)
    {
        // Ensure instructors exist first
        if (!context.Instructors.Any())
            SeedInstructors(context);

        context.Departments.AddRange(
            new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = new DateTime(2007, 9, 1), InstructorID = 10 },
            new Department { DepartmentID = 2, Name = "Mathematics", Budget = 100000, StartDate = new DateTime(2007, 9, 1), InstructorID = 11 }
        );
        context.SaveChanges();
    }

    public static void SeedCourses(SchoolContext context)
    {
        if (!context.Departments.Any())
            SeedDepartments(context);

        context.Courses.AddRange(
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 2 }
        );
        context.SaveChanges();
    }

    public static void SeedFull(SchoolContext context)
    {
        SeedStudents(context);
        SeedInstructors(context);
        SeedDepartments(context);
        SeedCourses(context);

        // Add enrollments
        context.Enrollments.AddRange(
            new Enrollment { EnrollmentID = 1, StudentID = 1, CourseID = 1050, Grade = Grade.A },
            new Enrollment { EnrollmentID = 2, StudentID = 1, CourseID = 4022, Grade = Grade.B },
            new Enrollment { EnrollmentID = 3, StudentID = 2, CourseID = 1050, Grade = Grade.C }
        );
        context.SaveChanges();

        // Add course assignments
        context.CourseAssignments.Add(new CourseAssignment { InstructorID = 10, CourseID = 1050 });
        context.SaveChanges();
    }
}

