using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateContext();
        TestHelpers.SeedStudents(_context);
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // === Index ===

    [Fact]
    public void Index_NoParams_ReturnsViewWithAllStudents()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Anand", model[0].LastName);
        Assert.Equal("Alexander", model[model.Count - 1].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        // 2020, 2021, 2022
        Assert.True(model[0].EnrollmentDate <= model[1].EnrollmentDate);
        Assert.True(model[1].EnrollmentDate <= model[2].EnrollmentDate);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.True(model[0].EnrollmentDate >= model[1].EnrollmentDate);
    }

    [Fact]
    public void Index_SearchString_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Carson", null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Carson", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SearchString_ResetsPage()
    {
        var result = _controller.Index(null, null, "A", null) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        var result = _controller.Index(null, "Alexander", null, 1) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Index_SetsViewBagCurrentSort()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;
        Assert.Equal("name_desc", _controller.ViewBag.CurrentSort);
    }

    [Fact]
    public void Index_SetsViewBagNameSortParm()
    {
        // When sortOrder is empty, NameSortParm should be "name_desc"
        _controller.Index(null, null, null, null);
        Assert.Equal("name_desc", (string)_controller.ViewBag.NameSortParm);

        // When sortOrder is "name_desc", NameSortParm should be ""
        _controller.Index("name_desc", null, null, null);
        Assert.Equal("", (string)_controller.ViewBag.NameSortParm);
    }

    [Fact]
    public void Index_SetsViewBagDateSortParm()
    {
        _controller.Index(null, null, null, null);
        Assert.Equal("Date", (string)_controller.ViewBag.DateSortParm);

        _controller.Index("Date", null, null, null);
        Assert.Equal("date_desc", (string)_controller.ViewBag.DateSortParm);
    }

    // === Details ===

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        // Need enrollments for the Include query
        _context.Enrollments.Add(new Enrollment { StudentID = 1, CourseID = 1050, Course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 } });
        _context.SaveChanges();

        var result = _controller.Details(1) as ViewResult;
        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
        Assert.Equal("Carson", student.FirstMidName);
        Assert.Equal(1, student.ID);
    }

    // === Create (GET) ===

    [Fact]
    public void Create_Get_ReturnsViewWithNewStudentAndDefaultDate()
    {
        var result = _controller.Create() as ViewResult;
        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    // === Create (POST) ===

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student) as RedirectToActionResult;
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_Post_ValidStudent_SavesStudentToDatabase()
    {
        var student = new Student
        {
            FirstMidName = "NewFirst",
            LastName = "NewLast",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _controller.Create(student);
        var saved = _context.Students.FirstOrDefault(s => s.LastName == "NewLast");
        Assert.NotNull(saved);
        Assert.Equal("NewFirst", saved.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), saved.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;
        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_DateBefore1753_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student) as ViewResult;
        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student { EnrollmentDate = new DateTime(2023, 1, 1) };

        var result = _controller.Create(student) as ViewResult;
        Assert.NotNull(result);
        Assert.Same(student, result.Model);
    }

    // === Edit (GET) ===

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Edit(1) as ViewResult;
        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Edit_Get_NotFoundId_ReturnsNotFound()
    {
        var result = _controller.Edit(999);
        Assert.IsType<NotFoundResult>(result);
    }

    // === Edit (POST) ===

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        // Detach existing entity to avoid tracking conflict
        var existing = _context.Students.Find(1)!;
        _context.Entry(existing).State = EntityState.Detached;

        var student = new Student
        {
            ID = 1,
            FirstMidName = "Updated",
            LastName = "Alexander",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };

        var result = _controller.Edit(student) as RedirectToActionResult;
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Edit(student) as ViewResult;
        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student { ID = 1, EnrollmentDate = new DateTime(2023, 1, 1) };

        var result = _controller.Edit(student) as ViewResult;
        Assert.NotNull(result);
    }

    // === Delete (GET) ===

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Delete(1) as ViewResult;
        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Delete_Get_NotFoundId_ReturnsNotFound()
    {
        var result = _controller.Delete(999);
        Assert.IsType<NotFoundResult>(result);
    }

    // === DeleteConfirmed (POST) ===

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var countBefore = _context.Students.Count();
        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(countBefore - 1, _context.Students.Count());
        Assert.Null(_context.Students.Find(1));
    }
}

