using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestHelpers.CreateContext();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.First(s => s.LastName == "User");
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 9001, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Find(9001);
        Assert.NotNull(retrieved);
        Assert.Equal("TestCourse", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
    }

    [Fact]
    public void CanAddAndRetrieveInstructor()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Prof",
            LastName = "Teacher",
            HireDate = new DateTime(2020, 1, 1)
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.First(i => i.LastName == "Teacher");
        Assert.Equal("Prof", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2020, 1, 1), retrieved.HireDate);
    }

    [Fact]
    public void CanAddAndRetrieveDepartment()
    {
        var dept = new Department
        {
            Name = "Biology",
            Budget = 50000,
            StartDate = new DateTime(2023, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var retrieved = _context.Departments.First(d => d.Name == "Biology");
        Assert.Equal(50000m, retrieved.Budget);
    }

    [Fact]
    public void CanAddEnrollment()
    {
        var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        var course = new Course { CourseID = 8001, Title = "C", Credits = 1, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments.First(e => e.StudentID == student.ID && e.CourseID == course.CourseID);
        Assert.Equal(Grade.A, retrieved.Grade);
    }

    [Fact]
    public void CourseAssignment_CompositeKey_Works()
    {
        var instructor = new Instructor { FirstMidName = "X", LastName = "Y", HireDate = DateTime.Now };
        _context.Instructors.Add(instructor);
        var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        var course = new Course { CourseID = 7001, Title = "T", Credits = 1, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments.Find(course.CourseID, instructor.ID);
        Assert.NotNull(retrieved);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
    }

    [Fact]
    public void OfficeAssignment_OneToOne_WithInstructor()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Office",
            LastName = "Person",
            HireDate = DateTime.Now,
            OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => i.LastName == "Person");
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Student_Enrollments_Navigation()
    {
        var student = new Student { FirstMidName = "Nav", LastName = "Test", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course1 = new Course { CourseID = 6001, Title = "C1", Credits = 1, DepartmentID = dept.DepartmentID };
        var course2 = new Course { CourseID = 6002, Title = "C2", Credits = 2, DepartmentID = dept.DepartmentID };
        _context.Courses.AddRange(course1, course2);
        _context.SaveChanges();

        _context.Enrollments.AddRange(
            new Enrollment { StudentID = student.ID, CourseID = 6001, Grade = Grade.A },
            new Enrollment { StudentID = student.ID, CourseID = 6002, Grade = Grade.B }
        );
        _context.SaveChanges();

        var retrieved = _context.Students
            .Include(s => s.Enrollments)
            .First(s => s.LastName == "Test");
        Assert.Equal(2, retrieved.Enrollments.Count);
    }

    [Fact]
    public void Notification_CanAddAndRetrieve()
    {
        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test notification",
            CreatedAt = DateTime.Now,
            CreatedBy = "admin",
            IsRead = false
        };
        _context.Notifications.Add(notification);
        _context.SaveChanges();

        var retrieved = _context.Notifications.First();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("1", retrieved.EntityId);
        Assert.Equal("CREATE", retrieved.Operation);
        Assert.Equal("Test notification", retrieved.Message);
        Assert.Equal("admin", retrieved.CreatedBy);
        Assert.False(retrieved.IsRead);
    }
}

