using ContosoUniversity.Models;
using System;
using Xunit;

namespace ContosoUniversity.Tests;

public class ModelTests
{
    // === Person / FullName ===

    [Fact]
    public void Person_FullName_ReturnsLastNameCommaFirstName()
    {
        var student = new Student { FirstMidName = "John", LastName = "Doe", EnrollmentDate = DateTime.Now };
        Assert.Equal("Doe, John", student.FullName);
    }

    [Fact]
    public void Person_FullName_InstructorAlsoWorks()
    {
        var instructor = new Instructor { FirstMidName = "Jane", LastName = "Smith", HireDate = DateTime.Now };
        Assert.Equal("Smith, Jane", instructor.FullName);
    }

    // === ErrorViewModel ===

    [Fact]
    public void ErrorViewModel_ShowRequestId_TrueWhenSet()
    {
        var model = new ErrorViewModel { RequestId = "abc123" };
        Assert.True(model.ShowRequestId);
        Assert.Equal("abc123", model.RequestId);
    }

    [Fact]
    public void ErrorViewModel_ShowRequestId_FalseWhenNull()
    {
        var model = new ErrorViewModel { RequestId = null };
        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ErrorViewModel_ShowRequestId_FalseWhenEmpty()
    {
        var model = new ErrorViewModel { RequestId = "" };
        Assert.False(model.ShowRequestId);
    }

    // === Course ===

    [Fact]
    public void Course_Properties()
    {
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/uploads/img.jpg"
        };

        Assert.Equal(1050, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
        Assert.Equal(1, course.DepartmentID);
        Assert.Equal("/uploads/img.jpg", course.TeachingMaterialImagePath);
    }

    // === Department ===

    [Fact]
    public void Department_Properties()
    {
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "English",
            Budget = 350000,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = 5
        };

        Assert.Equal(1, dept.DepartmentID);
        Assert.Equal("English", dept.Name);
        Assert.Equal(350000m, dept.Budget);
        Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
        Assert.Equal(5, dept.InstructorID);
    }

    [Fact]
    public void Department_InstructorID_CanBeNull()
    {
        var dept = new Department { Name = "NoAdmin", Budget = 1000, StartDate = DateTime.Now };
        Assert.Null(dept.InstructorID);
    }

    // === Enrollment ===

    [Fact]
    public void Enrollment_Properties()
    {
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 1050,
            StudentID = 1,
            Grade = Grade.A
        };

        Assert.Equal(1, enrollment.EnrollmentID);
        Assert.Equal(1050, enrollment.CourseID);
        Assert.Equal(1, enrollment.StudentID);
        Assert.Equal(Grade.A, enrollment.Grade);
    }

    [Fact]
    public void Enrollment_Grade_CanBeNull()
    {
        var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 1, StudentID = 1 };
        Assert.Null(enrollment.Grade);
    }

    // === Notification ===

    [Fact]
    public void Notification_Properties()
    {
        var now = DateTime.Now;
        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "New student",
            CreatedAt = now,
            CreatedBy = "admin",
            IsRead = false,
            ReadAt = null
        };

        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New student", notification.Message);
        Assert.Equal(now, notification.CreatedAt);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Null(notification.ReadAt);
    }

    [Fact]
    public void Notification_ReadAt_CanBeSet()
    {
        var readTime = DateTime.Now;
        var notification = new Notification
        {
            EntityType = "X",
            EntityId = "1",
            Operation = "READ",
            Message = "M",
            CreatedAt = DateTime.Now,
            IsRead = true,
            ReadAt = readTime
        };
        Assert.True(notification.IsRead);
        Assert.Equal(readTime, notification.ReadAt);
    }

    // === EntityOperation enum ===

    [Fact]
    public void EntityOperation_HasExpectedValues()
    {
        Assert.Equal(0, (int)EntityOperation.CREATE);
        Assert.Equal(1, (int)EntityOperation.UPDATE);
        Assert.Equal(2, (int)EntityOperation.DELETE);
    }

    // === Grade enum ===

    [Fact]
    public void Grade_HasExpectedValues()
    {
        Assert.Equal(0, (int)Grade.A);
        Assert.Equal(1, (int)Grade.B);
        Assert.Equal(2, (int)Grade.C);
        Assert.Equal(3, (int)Grade.D);
        Assert.Equal(4, (int)Grade.F);
    }

    // === OfficeAssignment ===

    [Fact]
    public void OfficeAssignment_Properties()
    {
        var oa = new OfficeAssignment { InstructorID = 5, Location = "Smith 17" };
        Assert.Equal(5, oa.InstructorID);
        Assert.Equal("Smith 17", oa.Location);
    }

    // === CourseAssignment ===

    [Fact]
    public void CourseAssignment_Properties()
    {
        var ca = new CourseAssignment { InstructorID = 1, CourseID = 1050 };
        Assert.Equal(1, ca.InstructorID);
        Assert.Equal(1050, ca.CourseID);
    }

    // === SchoolViewModels ===

    [Fact]
    public void AssignedCourseData_Properties()
    {
        var data = new ContosoUniversity.Models.SchoolViewModels.AssignedCourseData
        {
            CourseID = 101,
            Title = "TestCourse",
            Assigned = true
        };
        Assert.Equal(101, data.CourseID);
        Assert.Equal("TestCourse", data.Title);
        Assert.True(data.Assigned);
    }

    [Fact]
    public void EnrollmentDateGroup_Properties()
    {
        var group = new ContosoUniversity.Models.SchoolViewModels.EnrollmentDateGroup
        {
            EnrollmentDate = new DateTime(2023, 9, 1),
            StudentCount = 42
        };
        Assert.Equal(new DateTime(2023, 9, 1), group.EnrollmentDate);
        Assert.Equal(42, group.StudentCount);
    }

    [Fact]
    public void EnrollmentDateGroup_NullableDate()
    {
        var group = new ContosoUniversity.Models.SchoolViewModels.EnrollmentDateGroup
        {
            EnrollmentDate = null,
            StudentCount = 0
        };
        Assert.Null(group.EnrollmentDate);
    }

    [Fact]
    public void InstructorIndexData_Properties()
    {
        var data = new ContosoUniversity.Models.SchoolViewModels.InstructorIndexData
        {
            Instructors = Array.Empty<Instructor>(),
            Courses = Array.Empty<Course>(),
            Enrollments = Array.Empty<Enrollment>()
        };
        Assert.Empty(data.Instructors);
        Assert.Empty(data.Courses);
        Assert.Empty(data.Enrollments);
    }
}

