using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class DbInitializerTests : IDisposable
{
    private readonly SchoolContext _context;

    public DbInitializerTests()
    {
        _context = TestHelpers.CreateContext();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void Initialize_SeedsStudents()
    {
        DbInitializer.Initialize(_context);
        Assert.Equal(8, _context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsInstructors()
    {
        DbInitializer.Initialize(_context);
        Assert.Equal(5, _context.Instructors.Count());
    }

    [Fact]
    public void Initialize_SeedsDepartments()
    {
        DbInitializer.Initialize(_context);
        Assert.Equal(4, _context.Departments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourses()
    {
        DbInitializer.Initialize(_context);
        Assert.Equal(7, _context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsEnrollments()
    {
        DbInitializer.Initialize(_context);
        Assert.Equal(11, _context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        DbInitializer.Initialize(_context);
        Assert.Equal(3, _context.OfficeAssignments.Count());
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        DbInitializer.Initialize(_context);
        Assert.Equal(8, _context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_IdempotentWhenAlreadySeeded()
    {
        DbInitializer.Initialize(_context);
        var countBefore = _context.Students.Count();

        // Call again - should not add duplicates
        DbInitializer.Initialize(_context);
        Assert.Equal(countBefore, _context.Students.Count());
    }

    [Fact]
    public void Initialize_StudentNames_AreCorrect()
    {
        DbInitializer.Initialize(_context);
        var studentNames = _context.Students.Select(s => s.LastName).OrderBy(n => n).ToList();
        Assert.Contains("Alexander", studentNames);
        Assert.Contains("Alonso", studentNames);
        Assert.Contains("Li", studentNames);
        Assert.Contains("Olivetto", studentNames);
    }

    [Fact]
    public void Initialize_DepartmentBudgets_AreCorrect()
    {
        DbInitializer.Initialize(_context);
        var english = _context.Departments.First(d => d.Name == "English");
        Assert.Equal(350000m, english.Budget);

        var math = _context.Departments.First(d => d.Name == "Mathematics");
        Assert.Equal(100000m, math.Budget);
    }

    [Fact]
    public void Initialize_CourseCredits_AreCorrect()
    {
        DbInitializer.Initialize(_context);
        var calc = _context.Courses.First(c => c.Title == "Calculus");
        Assert.Equal(4, calc.Credits);

        var chem = _context.Courses.First(c => c.Title == "Chemistry");
        Assert.Equal(3, chem.Credits);
    }

    [Fact]
    public void Initialize_EnrollmentGrades_AreCorrect()
    {
        DbInitializer.Initialize(_context);
        var alexanderEnrollments = _context.Enrollments
            .Include(e => e.Student)
            .Include(e => e.Course)
            .Where(e => e.Student.LastName == "Alexander")
            .ToList();

        Assert.Equal(3, alexanderEnrollments.Count);
        var chemistryEnrollment = alexanderEnrollments.First(e => e.Course.Title == "Chemistry");
        Assert.Equal(Grade.A, chemistryEnrollment.Grade);
    }
}

